<?phpuse App\Http\Controllers\Api\AuthController;use App\Http\Controllers\Api\BookingController;use App\Http\Controllers\Api\FavoriteController;use App\Http\Controllers\Api\PlayGroundController;use App\Http\Controllers\Api\ReviewController;  // ← أضف هذاuse Illuminate\Support\Facades\Route;Route::post('/login', [AuthController::class, 'login']);Route::post('/register', [AuthController::class, 'register']);Route::middleware('auth:sanctum')->group(function () {    Route::get('/me', [AuthController::class, 'me']);    Route::post('/logout', [AuthController::class, 'logout']);    Route::get('/playgrounds', [PlayGroundController::class, 'index']);    Route::get('/playgrounds/{play_ground_id}/available-hours', [PlayGroundController::class, 'availableHours']);    // Bookings    Route::apiResource('bookings', BookingController::class);    Route::post('/bookings/{booking}/pay', [BookingController::class, 'pay']);    // Favorites    Route::post('/favorites', [FavoriteController::class, 'store']);    Route::delete('/favorites/{play_ground_id}', [FavoriteController::class, 'destroy']);    // Reviews    Route::apiResource('reviews', ReviewController::class);  // ← أضف هذا});